export function parseModelText(payload) {
  if (payload == null) return '';
  if (typeof payload === 'string') return payload;
  if (typeof payload.response === 'string') return payload.response;
  if (typeof payload.result === 'string') return payload.result;
  if (typeof payload.result?.response === 'string') return payload.result.response;
  if (typeof payload.output_text === 'string') return payload.output_text;
  const choice = payload.choices?.[0]?.message?.content ?? payload.choices?.[0]?.text;
  if (typeof choice === 'string') return choice;
  if (typeof payload.response === 'object' && payload.response) return JSON.stringify(payload.response);
  return '';
}
export function parseJsonObject(text) {
  if (typeof text !== 'string') return null;
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'); const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) { try { return JSON.parse(text.slice(start, end + 1)); } catch {} }
  return null;
}
