// Headless-browser render check against fictional fixtures and the local build.
// Requires a prior `npm run build` and a Chromium/Chrome binary on PATH.
// No external traffic and no live data; fixtures only exist under Miniflare.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';
import { Miniflare, convertV4MiniflareOptions, Log, LogLevel } from 'miniflare';
import { createFixtureFetch } from './fixtures.js';

const browser = ['chromium', 'chromium-browser', 'google-chrome', 'google-chrome-stable']
  .find((name) => spawnSync('which', [name]).status === 0);
if (!browser) { console.error('No Chromium/Chrome binary found on PATH; browser check skipped. Install one to run this check.'); process.exit(2); }
if (!existsSync('dist/worker.js')) { console.error('dist/worker.js is missing; run `npm run build` before `npm run test:browser`.'); process.exit(2); }

const port = await new Promise((resolve) => {
  const server = net.createServer();
  server.listen(0, '127.0.0.1', () => { const chosen = server.address().port; server.close(() => resolve(chosen)); });
});
const fixture = createFixtureFetch();
const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, port, log: new Log(LogLevel.ERROR), host: '127.0.0.1',
  name: 'positivity-bias', scriptPath: 'dist/worker.js', modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'NewsStore', useSQLite: true } },
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } },
  outboundService: fixture.fetch
}));
try {
  await mf.ready;
  const namespace = await mf.getDurableObjectNamespace('NEWS');
  await namespace.get(namespace.idFromName('edition')).fetch('https://news.internal/refresh', { method: 'POST' });
  const render = (args) => spawnSync(browser, ['--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--virtual-time-budget=8000', ...args], { encoding: 'utf8', timeout: 90_000 });
  const dom = render(['--dump-dom', `http://127.0.0.1:${port}/`]);
  assert.equal(dom.status, 0, dom.stderr);
  const html = dom.stdout || '';
  assert.match(html, /dir="rtl"/);
  assert.match(html, /lang="he"/);
  assert.ok((html.match(/class="article"/g) || []).length >= 4, 'no rendered article rows');
  assert.ok((html.match(/class="source-card"/g) || []).length === 4, 'expected four source status cards');
  assert.ok(html.includes('לפי המועצה: 3 תוכניות אושרו'), 'fixture headline not rendered');
  assert.ok(html.includes('כותרת מקור'), 'original-title label missing');
  assert.doesNotMatch(html, /SyntaxError|ReferenceError|TypeError/);
  for (const [width, height, file] of [[390, 844, 'mobile'], [1440, 1000, 'desktop']]) {
    const shot = render([`--window-size=${width},${height}`, `--screenshot=${join(tmpdir(), `positivity-bias-${file}.png`)}`, `http://127.0.0.1:${port}/`]);
    assert.equal(shot.status, 0, shot.stderr);
  }
  console.log(`Browser render passed: RTL Hebrew page, rendered article rows and source cards, original-title label; screenshots in ${tmpdir()}.`);
} finally { await mf.dispose(); }

// Explicitly fictional fixtures for the local Worker-runtime checks. No external traffic.
// Returned documents never reach the live site; they exist only inside Miniflare.
export function createFixtureFetch() {
  const publishedAt = new Date(Date.now() - 300_000).toISOString();
  let requests = 0;
  const fetch = async (request) => {
    const url = new URL(request.url);
    requests++;
    if (url.pathname.includes('/sitemap/')) {
      return new Response(`<urlset><url><loc>https://www.kan.org.il/content/kan-news/fixture</loc><news:news><news:title>לפי המועצה: 3 תוכניות אושרו</news:title><news:publication_date>${publishedAt}</news:publication_date></news:news></url></urlset>`);
    }
    if (url.pathname.includes('/kan-news/')) {
      return new Response(`<html><head><script type="application/ld+json">${JSON.stringify({ '@type': 'NewsArticle', headline: 'לפי המועצה: 3 תוכניות אושרו', description: 'ידיעה בדיונית לבדיקת תוכנה בלבד.', articleSection: 'בארץ', datePublished: publishedAt })}</script></head></html>`);
    }
    const domain = url.hostname.includes('ynet') ? 'www.ynet.co.il' : url.pathname.includes('news-') ? 'www.n12.co.il' : 'www.mako.co.il';
    const id = [...url.pathname].reduce((sum, char) => sum * 31 + char.charCodeAt(0) >>> 0, 0).toString(16);
    return new Response(`<rss><channel><item><title>לפי המועצה: 3 תוכניות אושרו</title><link>https://${domain}/news/Article-${id}.htm</link><pubDate>${publishedAt}</pubDate><category>קהילה</category><description>ידיעה בדיונית לבדיקת תוכנה בלבד.</description></item></channel></rss>`);
  };
  return { fetch, count: () => requests };
}

// Workerd-level check of the full-text extraction policy. Plain Node has no
// HTMLRewriter, so the probe is bundled with esbuild and run inside Miniflare.
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { build } from 'esbuild';
import { Miniflare, convertV4MiniflareOptions } from 'miniflare';

// The bundle must live under the working directory so workerd resolves it.
const directory = await mkdtemp(join(process.cwd(), '.probe-'));
const outfile = join(directory, 'probe.js');
await build({ entryPoints: ['scripts/extract-probe.js'], bundle: true, format: 'esm', platform: 'browser', target: 'es2022', outfile });

const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, name: 'extract-probe', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13'
}));

try {
  await mf.ready;
  const data = await (await mf.dispatchFetch('https://probe.local/')).json();
  assert.equal(data.headline, 'התעשייה האווירית השלימה בהצלחה ניסוי במל״ט');
  assert.deepEqual(data.categories, ['בטחון']);
  assert.equal(data.completeness, 'complete');
  assert.match(data.body, /השלימה בהצלחה ניסוי במל״ט/);
  assert.match(data.body, /הניסוי נערך באזור דרומי/);
  for (const noise of ['דף הבית', 'ספורט', 'פרסומת', 'כתבות נוספות', 'מומלץ עבורך', 'כל הזכויות שמורות']) {
    assert.ok(!data.body.includes(noise), `noise leaked into context: ${noise}`);
  }
  console.log('Extraction passed: article body kept, navigation/advertising/related/footer removed, JSON-LD metadata read.');
} finally { await mf.dispose(); await rm(directory, { recursive: true, force: true }); }

