// Explicitly fictional fixtures for the local Worker-runtime checks. No external traffic.
// Returned documents never reach the live site; they exist only inside Miniflare.
export function createFixtureFetch() {
  const publishedAt = new Date(Date.now() - 300_000).toISOString();
  let requests = 0;
  const fetch = async (request) => {
    const url = new URL(request.url);
    requests++;
    if (url.pathname.includes('/sitemap/')) {
      return new Response(`<urlset><url><loc>https://www.kan.org.il/content/kan-news/fixture</loc><news:news><news:title>לפי המועצה: 3 תוכניות אושרו</news:title><news:publication_date>${publishedAt}</news:publication_date></news:news></url></urlset>`);
    }
    if (url.pathname.includes('/kan-news/')) {
      return new Response(`<html><head><script type="application/ld+json">${JSON.stringify({ '@type': 'NewsArticle', headline: 'לפי המועצה: 3 תוכניות אושרו', description: 'ידיעה בדיונית לבדיקת תוכנה בלבד.', articleSection: 'בארץ', datePublished: publishedAt })}</script></head></html>`);
    }
    const domain = url.hostname.includes('ynet') ? 'www.ynet.co.il' : url.pathname.includes('news-') ? 'www.n12.co.il' : 'www.mako.co.il';
    const id = [...url.pathname].reduce((sum, char) => sum * 31 + char.charCodeAt(0) >>> 0, 0).toString(16);
    return new Response(`<rss><channel><item><title>לפי המועצה: 3 תוכניות אושרו</title><link>https://${domain}/news/Article-${id}.htm</link><pubDate>${publishedAt}</pubDate><category>קהילה</category><description>ידיעה בדיונית לבדיקת תוכנה בלבד.</description></item></channel></rss>`);
  };
  return { fetch, count: () => requests };
}

// Local Worker-runtime checks with explicitly fictional fixtures; no external traffic.
import assert from 'node:assert/strict';
import { Miniflare, convertV4MiniflareOptions, Log, LogLevel } from 'miniflare';
import { createFixtureFetch } from './fixtures.js';

const fixture = createFixtureFetch();

const mfOptions = convertV4MiniflareOptions({
  cf: false,
  log: new Log(LogLevel.DEBUG),
  name: 'positivity-bias', scriptPath: 'dist/worker.js', modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'NewsStore', useSQLite: true } },
  // Wrangler marks the Worker as the user worker; the raw Miniflare v4 options
  // must set has_user_worker explicitly or the assets router cannot dispatch /api/*.
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } },
  bindings: {},
  outboundService: fixture.fetch
});
mfOptions.handleUncaughtError = (error) => console.error('Fixture runtime error:', error);
const mf = new Miniflare(mfOptions);

try {
  await mf.ready;
  const namespace = await mf.getDurableObjectNamespace('NEWS');
  const store = namespace.get(namespace.idFromName('edition'));
  const refresh = await store.fetch('https://news.internal/refresh', { method: 'POST' });
  assert.equal(refresh.status, 200, await refresh.clone().text());
  assert.equal((await refresh.json()).state, 'complete');
  const result = await mf.dispatchFetch('https://fixture.local/api/news');
  assert.equal(result.status, 200);
  const data = await result.json();
  assert.equal(data.sources.length, 4);
  assert.ok(data.sources.every((source) => source.state === 'ok'));
  assert.deepEqual(new Set(data.articles.map((article) => article.sourceId)), new Set(['ynet', 'kan', 'n12', 'mako']));
  assert.ok(data.articles.every((article) => article.rewriteStatus === 'original'));
  assert.ok(data.articles.every((article) => article.originalHeadline.includes(':') && !('description' in article)));
  assert.ok(data.categories.includes('בארץ') && data.categories.includes('קהילה'));
  assert.equal(data.stale, false);
  assert.equal(data.rewriteStatus, 'not_configured');
  const requestsBeforeCooldown = fixture.count();
  assert.equal((await (await store.fetch('https://news.internal/refresh', { method: 'POST' })).json()).state, 'cooldown');
  assert.equal(fixture.count(), requestsBeforeCooldown);
  const filtered = await (await mf.dispatchFetch('https://fixture.local/api/news?source=kan&limit=1')).json();
  assert.equal(filtered.articles.length, 1); assert.equal(filtered.articles[0].sourceId, 'kan');
  const unmatched = await (await mf.dispatchFetch('https://fixture.local/api/news?q=nomatch')).json();
  assert.equal(unmatched.total, 0);
  const byCategory = await (await mf.dispatchFetch(`https://fixture.local/api/news?category=${encodeURIComponent('קהילה')}&limit=120`)).json();
  assert.ok(byCategory.articles.length > 0);
  assert.ok(byCategory.articles.every((article) => article.categories.includes('קהילה')));
  const latest = await (await mf.dispatchFetch('https://fixture.local/api/news?order=latest&limit=120')).json();
  const times = latest.articles.map((article) => article.publishedAt);
  assert.deepEqual(times, [...times].sort((a, b) => b.localeCompare(a))); // chronological order is exact
  const firstPage = await (await mf.dispatchFetch('https://fixture.local/api/news?limit=5')).json();
  const secondPage = await (await mf.dispatchFetch('https://fixture.local/api/news?limit=5&offset=5')).json();
  assert.equal(firstPage.articles.length, 5);
  assert.equal(firstPage.total, secondPage.total);
  assert.ok(firstPage.total > 5);
  const firstIds = new Set(firstPage.articles.map((article) => article.id));
  assert.ok(secondPage.articles.every((article) => !firstIds.has(article.id)), 'pagination pages overlap');
  const status = await (await mf.dispatchFetch('https://fixture.local/api/status')).json();
  assert.equal(status.stale, false);
  assert.equal(status.sources.length, 4);
  assert.ok(!('articles' in status) && !('categories' in status)); // status stays summary-only
  const page = await mf.dispatchFetch('https://fixture.local/');
  assert.equal(page.status, 200); assert.match(await page.text(), /dir="rtl"/);
  assert.equal((await mf.dispatchFetch('https://fixture.local/style.css')).status, 200);
  assert.equal((await mf.dispatchFetch('https://fixture.local/api/refresh', { method: 'POST' })).status, 405);
  assert.equal((await mf.dispatchFetch('https://fixture.local/api/unknown')).status, 404);
  console.log(`Worker runtime passed: SQLite persistence, all four adapters, HTMLRewriter metadata, original fallback without an AI binding, categories, API filters/order/pagination/status, cooldown, and static assets (${fixture.count()} publisher requests).`);
} finally { await mf.dispose(); }

// Integration regression: when many full-text articles are pending, the shared
// rewrite+verify batches must be split so that no verification request exceeds the
// validator's context window. A rewrite-only plan (Llama's 128k window) would pack
// ~20 articles (~80k tokens) into one request against clef-flash's 32k window.
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { build } from 'esbuild';
import { Miniflare, convertV4MiniflareOptions } from 'miniflare';
import { ESTIMATED_CHARS_PER_TOKEN } from '../src/budget.js';
import { MODEL_CONTEXT_TOKENS } from '../src/policy.js';

const directory = await mkdtemp(join(process.cwd(), '.probe-'));
const outfile = join(directory, 'probe.js');
await build({ entryPoints: ['scripts/batch-probe.js'], bundle: true, format: 'esm', platform: 'browser', target: 'es2022', outfile });

const COUNT = 9;
const now = Date.now();
// Each page body is long enough to be truncated at the 6000-char context cap, so the
// plan must split a 9-article pending set across multiple 32k-token requests.
const longBody = 'המועצה דנה בתכניות הפיתוח של האזור ובהשלכותיהן על התושבים. '.repeat(200);

const fixture = async (request) => {
  const match = /^\/page\/(\d+)$/.exec(new URL(request.url).pathname);
  if (!match) return new Response('not found', { status: 404 });
  const n = Number(match[1]);
  const html = `<!doctype html><html lang="he"><head>
    <script type="application/ld+json">${JSON.stringify({ '@type': 'NewsArticle', headline: `עדכון כללי ${n}`, articleSection: 'בארץ' })}</script>
  </head><body><nav>ניווט באתר</nav><article><h1>עדכון כללי</h1><p>${longBody}</p></article><div class="related"><p>כתבות קשורות</p></div></body></html>`;
  return new Response(html, { headers: { 'content-type': 'text/html' } });
};

const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, name: 'positivity-bias', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'BatchStore', useSQLite: true } },
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } },
  outboundService: fixture
}));

try {
  await mf.ready;
  const namespace = await mf.getDurableObjectNamespace('NEWS');
  const store = namespace.get(namespace.idFromName('edition'));
  const articles = Array.from({ length: COUNT }, (_, index) => ({
    id: `https://www.ynet.co.il/page/${index + 1}`, url: `https://www.ynet.co.il/page/${index + 1}`,
    sourceId: 'ynet', sourceName: 'ynet', originalHeadline: `עדכון כללי ${index + 1}`, headline: `עדכון כללי ${index + 1}`,
    description: 'תיאור', categories: ['בארץ'], publishedAt: new Date(now - 60_000).toISOString(), rewriteStatus: 'original'
  }));
  const seeded = { articles, updatedAt: new Date(now - 60_000).toISOString(),
    lastAttemptAt: new Date(now - 2 * 3_600_000).toISOString(), policyFingerprint: null, rewriteStatus: 'not_configured', sources: [] };
  const run = await (await store.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: seeded,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '6000', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '20' } }) })).json();
  assert.equal(run.result.state, 'complete');
  assert.equal(run.result.rewriteStatus, 'ok');
  assert.equal(run.result.articles, COUNT);
  // The shared batch is split by the smaller (validator) window, not the rewrite model's.
  assert.ok(run.calls.rewrite > 1, `expected split batches, got ${run.calls.rewrite}`);
  assert.equal(run.calls.verify, run.calls.rewrite);
  const window = MODEL_CONTEXT_TOKENS['@cf/cloudflare/clef-flash'];
  const verifyTokens = Math.ceil(run.calls.maxVerifyChars / ESTIMATED_CHARS_PER_TOKEN);
  assert.ok(verifyTokens <= window, `verification request ~${verifyTokens} tokens exceeds validator window ${window}`);
  assert.ok(run.calls.maxRewriteChars <= run.calls.maxVerifyChars + 200, 'rewrite request is not larger than verification');

  const api = await (await mf.dispatchFetch('https://fixture.local/api/news?limit=120')).json();
  assert.equal(api.total, COUNT);
  assert.ok(api.articles.every((article) => article.rewriteStatus === 'rewritten'));
  assert.ok(api.articles.every((article) => !('context' in article) && !('verification' in article)));
  const day = new Date().toISOString().slice(0, 10);
  const usage = await (await store.fetch(`https://news.internal/usage?day=${day}`)).json();
  assert.ok(usage.used > 0 && usage.used <= 6000, `unexpected usage ${usage.used}`);
  console.log(`Batch passed: ${COUNT} full-text articles split into ${run.calls.rewrite} requests, each verification within the ${window}-token validator window; usage ${Math.round(usage.used)} neurons.`);
} finally { await mf.dispose().catch(() => {}); await rm(directory, { recursive: true, force: true }).catch(() => {}); }

