// Guards the dist-based runtime checks: they must exercise the CURRENT source, not a
// stale or missing Wrangler bundle. `npm run test:worker|browser|interaction` build
// first; a direct run refuses instead of silently validating old code.
import { existsSync, statSync, readdirSync } from 'node:fs';

const SOURCE_ROOTS = ['src', 'websites.json', 'package.json'];

function newestSourceMtime() {
  let newest = 0;
  const visit = (path) => {
    const stat = statSync(path);
    if (stat.isDirectory()) { for (const entry of readdirSync(path)) visit(`${path}/${entry}`); }
    else newest = Math.max(newest, stat.mtimeMs);
  };
  for (const path of SOURCE_ROOTS) if (existsSync(path)) visit(path);
  return newest;
