// Guards the dist-based runtime checks so they exercise the CURRENT source instead of
// a stale or missing Wrangler bundle. `npm run test:worker|browser|interaction` build
// first; a direct `node scripts/...` run refuses rather than silently validating old
// code. The esbuild-based checks (extract/retirement/pipeline/batch) read `src/`
// directly and need no guard.
import { existsSync, readdirSync, statSync } from 'node:fs';

const SOURCE_ROOTS = ['src', 'websites.json', 'package.json'];

function newestSourceMtime() {
  let newest = 0;
  const visit = (path) => {
    const stat = statSync(path);
    if (stat.isDirectory()) { for (const entry of readdirSync(path)) visit(`${path}/${entry}`); }
    else newest = Math.max(newest, stat.mtimeMs);
  };
  for (const path of SOURCE_ROOTS) if (existsSync(path)) visit(path);
  return newest;
}

export function requireFreshBundle(command) {
  if (!existsSync('dist/worker.js')) {
    console.error(`dist/worker.js is missing; run \`npm run build\` before \`${command}\`.`);
    process.exit(2);
  }
  if (statSync('dist/worker.js').mtimeMs < newestSourceMtime()) {
    console.error(`dist/worker.js is older than the source; run \`npm run build\` before \`${command}\`.`);
    process.exit(2);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { DEFAULT_CONTEXT_CHARS, MIN_CONTEXT_CHARS, prepareContext } from '../src/extract.js';

const article = 'המועצה אישרה שלוש תוכניות חדשות. '.repeat(4);

test('Context completeness is tracked honestly instead of describing an excerpt as the article', () => {
  assert.deepEqual(prepareContext(''), { text: '', charCount: 0, completeness: 'missing' });
  const complete = prepareContext(`<p>${article}</p>`);
  assert.equal(complete.completeness, 'complete');
  assert.equal(complete.text, article.trim());
  const long = prepareContext('א'.repeat(DEFAULT_CONTEXT_CHARS + 500));
  assert.equal(long.completeness, 'truncated');
  assert.equal(long.text.length, DEFAULT_CONTEXT_CHARS);
  assert.ok(long.charCount > DEFAULT_CONTEXT_CHARS);
});

test('Thin navigation or stub text is treated as missing, never as the article', () => {
  const thin = prepareContext('תפריט האתר דלג לתוכן העמוד קישורים תחתונים');
  assert.ok('תפריט האתר דלג לתוכן העמוד קישורים תחתונים'.length < MIN_CONTEXT_CHARS);
  assert.equal(thin.completeness, 'missing');
  assert.equal(thin.text, '');
});

test('Bot-challenge and access-denied interstitials are never inference context', () => {
  for (const page of [
    'We are sorry... but your activity and behavior on this website made us think that you are a bot. To protect this website, we cannot process your request right now.',
    'Please solve this CAPTCHA in helping us understand your behavior to grant access.',
    'Access to this page has been denied because we believe you are using automation tools.'
  ]) {
    const result = prepareContext(page);
    assert.equal(result.completeness, 'missing');
    assert.equal(result.text, '');
  }
});

test('Context is bounded plain text without markup', () => {
  assert.equal(prepareContext(`<script>evil()</script><p>${article} &amp; עוד</p>`).text, `${article.trim()} & עוד`);
});

// Workerd-level check of the full-text extraction policy. Plain Node has no
// HTMLRewriter, so the probe is bundled with esbuild and run inside Miniflare.
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { build } from 'esbuild';
import { Miniflare, convertV4MiniflareOptions } from 'miniflare';

// The bundle must live under the working directory so workerd resolves it.
const directory = await mkdtemp(join(process.cwd(), '.probe-'));
const outfile = join(directory, 'probe.js');
await build({ entryPoints: ['scripts/extract-probe.js'], bundle: true, format: 'esm', platform: 'browser', target: 'es2022', outfile });

const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, name: 'extract-probe', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13'
}));

try {
  await mf.ready;
  // A self-closing SVG <path> in this page must not abort extraction (real pages have them).
  const data = await (await mf.dispatchFetch('https://probe.local/?case=article')).json();
  assert.equal(data.headline, 'התעשייה האווירית השלימה בהצלחה ניסוי במל״ט');
  assert.deepEqual(data.categories, ['בטחון']);
  assert.equal(data.completeness, 'complete');
  assert.match(data.body, /השלימה בהצלחה ניסוי במל״ט/);
  assert.match(data.body, /הניסוי נערך באזור דרומי/);
  for (const noise of ['דף הבית', 'ספורט', 'פרסומת', 'כתבות נוספות', 'מומלץ עבורך', 'כל הזכויות שמורות']) {
    assert.ok(!data.body.includes(noise), `noise leaked into context: ${noise}`);
  }
  const block = await (await mf.dispatchFetch('https://probe.local/?case=block')).json();
  assert.equal(block.completeness, 'missing');
  assert.equal(block.body, '');
  const thin = await (await mf.dispatchFetch('https://probe.local/?case=thin')).json();
  assert.equal(thin.completeness, 'missing');
  assert.equal(thin.body, '');
  console.log('Extraction passed: article body kept (self-closing SVG tolerated), navigation/advertising/related/footer removed, JSON-LD metadata read, bot-block and thin shells rejected.');
} finally { await mf.dispose(); await rm(directory, { recursive: true, force: true }); }

