// Clef is a decision model, not a chat model: it takes a `state` plus typed
// `questions` and returns a probability per question. Its documented schema and
// 24,576-token window differ completely from a chat completion, so it must not be
// called with `messages`/`response_format`.
export const CLEF_QUESTION_MODEL = 'clef-flash';
export const CLEF_MAX_QUESTIONS = 64;         // documented: 1..64 questions per call
export const CLEF_QUESTIONS_PER_CANDIDATE = 2; // supported + preserved
export const CLEF_MAX_CANDIDATES = Math.floor(CLEF_MAX_QUESTIONS / CLEF_QUESTIONS_PER_CANDIDATE); // 32
export const CLEF_ACCEPT_PROBABILITY = 0.5;   // documented answer is P(yes)

export const VERIFICATION_QUESTIONS = {
  supported: {
    type: 'noul',
    instructions: `Supported: for the candidate named in this question, is EVERY claim in its proposedHeadline supported by its article body or originalHeadline? Answer no if it contradicts the text or reverses an outcome, invents a fact, name, number or motive, states an attributed allegation or quote as established fact, or drops or changes required uncertainty, negation or attribution.`,
    criteria: { true: 'Every claim is supported.', false: 'A claim is contradicted, unsupported or invented.' }
  },
  preserved: {
    type: 'noul',
    instructions: `Preserved: for the candidate named in this question, does its proposedHeadline keep the article's primary point AND material context — the actual actor or speaker, action or claim, geographic or population scope, and result or addressee — with no misleading omission, broadening, narrowing or changed emphasis? Answer no for a merely plausible but incomplete headline, e.g. one that drops who spoke or where the statement applies, or replaces named speakers with a wider group.`,
    criteria: { true: 'Primary point and material context preserved.', false: 'Misleading omission, broadening, narrowing or changed emphasis.' }
  }
};

export const VERIFICATION_PROMPT = `${VERIFICATION_QUESTIONS.supported.instructions} ${VERIFICATION_QUESTIONS.preserved.instructions}`;
```

