// Split candidates into clef calls that respect the documented 64-question limit and
// the model's context window (state is truncated past it, which could hide a
// candidate). Article text is never truncated by us.
export function planVerificationBatches(candidates, { model = DEFAULT_VALIDATOR_MODEL } = {}) {
  const window = MODEL_CONTEXT_TOKENS[model] || 24_576;
  const batches = [];
  let current = [];
  let currentChars = 0;
  const fits = () => 400 + Math.ceil(currentChars / ESTIMATED_CHARS_PER_TOKEN) <= window;
  for (const candidate of candidates) {
    const itemChars = (candidate.context?.length || 0) + String(candidate.headline || '').length + VERIFY_QUESTION_CHARS_PER_CANDIDATE;
    if (current.length && (current.length >= CLEF_MAX_CANDIDATES || Math.ceil((currentChars + itemChars)/ESTIMATED_CHARS_PER_TOKEN) + 400 > window)) {
      batches.push(current); current = []; currentChars = 0;
    }
    current.push(candidate); currentChars += itemChars;
  }
  if (current.length) batches.push(current);
  return batches;
}
```

