import { plainText } from './text.js';
import { OUTPUT_TOKENS_PER_ITEM, estimateNeurons, ESTIMATED_CHARS_PER_TOKEN, VERIFY_QUESTION_CHARS_PER_CANDIDATE } from './budget.js';
