  [`${index}_supported`, { type: 'noul', noul: verdict.supported ? 1 : 0 }],
  [`${index}_preserved`, { type: 'noul', noul: verdict.preserved ? 1 : 0 }],
])) });
const clefEnv = (verdicts) => ({ AI: { run: async (model, input) => {
  assert.equal(model, DEFAULT_VALIDATOR_MODEL);
