// Temporary live probe (not committed): runs the real NewsStore refresh against the
// real publisher feeds with a recording mock model, so we can measure ingestion and
// full-text context completeness without any Cloudflare credentials.
import worker, { NewsStore } from './src/worker.js';

export class LiveStore extends NewsStore {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/live' && request.method === 'POST') {
      const recorded = [];
      const mock = {
        calls: { rewrite: 0, verify: 0 },
        run: async (model, input) => {
          if (model === 'clef-flash' || /clef/.test(model)) {
            mock.calls.verify++;
            const answers = {};
            input.state.forEach((item, index) => {
              answers[`${index}_supported`] = { type: 'noul', noul: 0.9 };
              answers[`${index}_preserved`] = { type: 'noul', noul: 0.9 };
            });
            return { model: 'clef-flash', answers, usage: { input_tokens: 1000, output_tokens: 0 } };
          }
          mock.calls.rewrite++;
          const items = JSON.parse(input.messages[1].content);
          for (const item of items) recorded.push({ id: item.id, source: item.source, completeness: item.contextCompleteness, chars: (item.article || '').length, originalHeadline: (item.originalHeadline || '').slice(0, 40) });
          return { response: JSON.stringify({ items: items.map((item) => ({ id: item.id, usable: true, headline: item.originalHeadline })) }) };
        }
      };
      this.env = { ...this.env, AI: mock };
      const result = await this.refresh();
      const snapshot = await this.fetch(new Request('https://news.internal/snapshot'));
      const snap = await snapshot.json();
      return Response.json({ result, calls: mock.calls, recorded,
        sourceStatus: snap.sources, articleCount: snap.articles.length,
        completeness: snap.articles.reduce((acc, a) => { acc[a.contextCompleteness || 'none'] = (acc[a.contextCompleteness || 'none'] || 0) + 1; return acc; }, {}) });
    }
    return super.fetch(request);
  }
}

export default worker;

