    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '6000', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '4' } }) })).json();
  assert.equal(run.result.state, 'complete');
  assert.equal(run.result.rewriteStatus, 'ok');
  assert.equal(run.calls.rewrite, 1); // one bounded batch
  assert.equal(run.calls.verify, 1); // one bounded verification call

  const api = await (await mf.dispatchFetch('https://fixture.local/api/news')).json();
  const byOriginal = new Map(api.articles.map((article) => [article.originalHeadline, article]));
  const accepted = byOriginal.get('לפי המועצה: 3 תוכניות אושרו');
  assert.equal(accepted.headline, 'לפי המועצה אושרו 3 תוכניות');
  assert.equal(accepted.rewriteStatus, 'rewritten');
  assert.equal(accepted.rewriteFingerprint, undefined); // fingerprint is internal
  const rejected = byOriginal.get('האוכלוסייה בישראל רואה את הצפון כצימר לסופ״ש אבל לא כמקום לגור בו');
  assert.equal(rejected.headline, rejected.originalHeadline); // failed verification keeps the original
  assert.equal(rejected.rewriteStatus, 'original');

  const day = new Date().toISOString().slice(0, 10);
  const usage = await (await store.fetch(`https://news.internal/usage?day=${day}`)).json();
  assert.ok(usage.used > 0 && usage.used <= 6000, `unexpected usage ${usage.used}`);

  // Cached decisions: a second refresh re-infers neither the accepted nor the rejected article.
  const cachedSeed = await (await store.fetch('https://news.internal/snapshot')).json();
  cachedSeed.lastAttemptAt = new Date(Date.now() - 2 * 3_600_000).toISOString();
  const cached = await (await store.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: cachedSeed,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '6000', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '4' } }) })).json();
  assert.equal(cached.calls.rewrite, 0);
  assert.equal(cached.calls.verify, 0);

  // Budget deferral: no budget means no model calls and originals kept.
  const deferredSeed = { articles: [], updatedAt: null, lastAttemptAt: new Date(Date.now() - 2 * 3_600_000).toISOString(),
    policyFingerprint: null, rewriteStatus: 'not_configured', sources: [] };
  const deferred = await (await store.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: deferredSeed,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '0', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '4' } }) })).json();
  assert.equal(deferred.result.rewriteStatus, 'budget_deferred');
  assert.equal(deferred.calls.rewrite, 0);
  assert.equal(deferred.calls.verify, 0);

  // An unparseable model response keeps the originals AND is reported honestly,
  // instead of a healthy `ok` that would hide a silently failing rewrite pipeline.
  const invalidStore = namespace.get(namespace.idFromName('invalid'));
  const invalidSeed = { articles: [], updatedAt: null, lastAttemptAt: new Date(Date.now() - 2 * 3_600_000).toISOString(),
    policyFingerprint: null, rewriteStatus: 'not_configured', sources: [] };
  const invalid = await (await invalidStore.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: invalidSeed,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '6000', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '4', MOCK_REWRITE: 'invalid' } }) })).json();
  assert.equal(invalid.result.state, 'complete');
  assert.equal(invalid.result.rewriteStatus, 'invalid_response');
  assert.ok(invalid.calls.rewrite > 0);
  assert.equal(invalid.calls.verify, 0); // nothing to verify without a parsed candidate
  const invalidServed = await (await invalidStore.fetch('https://news.internal/snapshot')).json();
  assert.ok(invalidServed.articles.length > 0);
  assert.ok(invalidServed.articles.every((article) => article.headline === article.originalHeadline)); // originals preserved
  assert.ok(invalidServed.articles.every((article) => article.rewriteStatus !== 'rewritten')); // and not cached as trusted

  // Retirement + reprocessing: a stale wrong cached headline must never be served, and
  // the same article must be reprocessed under the active policy within the same daily
  // budget. The original is restored first, then a fresh, correct rewrite replaces it.
  const staleWrong = 'כותרת שגויה: הניסוי במל״ט נכשל';
  const staleSeed = {
    articles: [{ id: 'https://ynet.co.il/news/article/1', url: 'https://www.ynet.co.il/news/article/1',
      sourceId: 'ynet', sourceName: 'ynet', originalHeadline: 'לפי המועצה: 3 תוכניות אושרו',
      headline: staleWrong, rewriteStatus: 'rewritten', rewriteFingerprint: 'old-policy',
      categories: ['בארץ'], description: 'תיאור', publishedAt: publishedAt.toISOString() }],
    updatedAt: null, lastAttemptAt: new Date(Date.now() - 2 * 3_600_000).toISOString(),
    policyFingerprint: 'old-policy', rewriteStatus: 'ok', sources: [] };
  const reprocessed = await (await store.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: staleSeed,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '6000', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '4' } }) })).json();
  assert.equal(reprocessed.result.state, 'complete');
  assert.ok(reprocessed.calls.rewrite > 0); // the retired article was reprocessed, not skipped
  const served = await (await mf.dispatchFetch('https://fixture.local/api/news')).json();
  assert.ok(!served.articles.some((article) => article.headline === staleWrong));
  const fixed = served.articles.find((article) => article.id === 'https://ynet.co.il/news/article/1');
  assert.ok(fixed, 'reprocessed article missing');
  assert.equal(fixed.rewriteStatus, 'rewritten');
  assert.equal(fixed.headline, 'לפי המועצה אושרו 3 תוכניות');
  console.log('Pipeline passed: full-text context, bounded rewrite+verify, independent acceptance/rejection, usage ledger, budget deferral, and stale-rewrite retirement with reprocessing.');
} finally { await mf.dispose().catch(() => {}); await rm(directory, { recursive: true, force: true }).catch(() => {}); }

const $ = (id) => document.getElementById(id);
const state = { order: 'broad', offset: 0, loading: false, controller: null, requestId: 0, filters: '' };
const dateFormat = new Intl.DateTimeFormat('he-IL', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Jerusalem' });
const timeFormat = new Intl.DateTimeFormat('he-IL', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jerusalem' });
$('edition-date').textContent = dateFormat.format(new Date());

function element(tag, className, value) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (value != null) node.textContent = value;
  return node;
}

function safeLink(value) {
  try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password ? url.href : null; } catch { return null; }
}

function renderArticle(article) {
  const url = safeLink(article.url);
  if (!url) return null;
  const row = element('article', 'article');
  const meta = element('div', 'article-meta');
  meta.append(element('span', 'article-source', article.sourceName));
  const time = element('time', 'article-time', timeFormat.format(new Date(article.publishedAt)));
  time.dateTime = article.publishedAt;
  meta.append(time, element('span', 'category-label', article.categories.join(' · ') || 'ללא קטגוריה במקור'));
  const content = element('div', 'article-content');
  const heading = element('h3', 'article-title');
  const link = element('a', '', article.headline); link.href = url; link.rel = 'noopener noreferrer'; heading.append(link);
  content.append(heading);
  if (article.rewriteStatus === 'rewritten') {
    const original = element('details', 'article-original');
    original.append(element('summary', '', 'הכותרת המקורית'), element('p', '', article.originalHeadline));
    content.append(original);
  }
  const action = element('div', 'article-action');
  const originalLink = element('a', 'text-link', 'לכתבה במקור'); originalLink.href = url; originalLink.rel = 'noopener noreferrer';
  const arrow = element('span', '', '↖'); arrow.setAttribute('aria-hidden', 'true'); originalLink.append(arrow);
  action.append(originalLink, element('span', article.rewriteStatus === 'rewritten' ? 'rewrite-label edited' : 'rewrite-label', article.rewriteStatus === 'rewritten' ? 'ניסוח ענייני' : 'כותרת מקור'));
  row.append(meta, content, action);
  return row;
}

function emptyState(title, copy, retry = false) {
  const block = element('div', 'empty-state');
  const mark = element('span', 'empty-mark', '↙'); mark.setAttribute('aria-hidden', 'true');
  block.append(mark, element('h3', '', title), element('p', '', copy));
  if (retry) { const button = element('button', 'button', 'לנסות שוב'); button.type = 'button'; button.addEventListener('click', () => load()); block.append(button); }
  return block;
}

function renderSources(sources) {
  const labels = { ok: 'העדכון האחרון התקבל', partial: 'חלק מהעדכונים זמינים', unavailable: 'המקור אינו זמין כרגע', pending: 'ממתינים לעדכון הראשון' };
  $('source-status').replaceChildren(...sources.map((source) => {
    const card = element('div', 'source-card');
    const link = element('a', '', source.name); link.href = `https://${source.domain}`; link.rel = 'noopener noreferrer';
    const status = element('p', 'source-state');
    const dot = element('span', source.state === 'ok' ? 'status-dot ok' : 'status-dot'); dot.setAttribute('aria-hidden', 'true');
    status.append(dot, document.createTextNode(labels[source.state] || labels.pending));
    card.append(link, status);
    if (source.lastSuccessAt) card.append(element('p', '', `עדכון שהתקבל: ${timeFormat.format(new Date(source.lastSuccessAt))}`));
    return card;
  }));
}

async function load(append = false) {
  const requestId = ++state.requestId;
  state.controller?.abort();
  state.controller = new AbortController(); state.loading = true;
  $('articles').setAttribute('aria-busy', 'true'); $('more').disabled = true;
  const params = new URLSearchParams(new FormData($('filters')));
  params.set('order', state.order); params.set('offset', String(append ? state.offset : 0)); params.set('limit', '30');
  state.filters = params.toString();
  try {
    const response = await fetch(`/api/news?${params}`, { signal: state.controller.signal });
    if (!response.ok) throw new Error('unavailable');
    const data = await response.json();
    if (requestId !== state.requestId) return;
    if (!append) { $('articles').replaceChildren(); state.offset = 0; }
    for (const article of data.articles) { const row = renderArticle(article); if (row) $('articles').append(row); }
    state.offset += data.articles.length;
    if (!state.offset) $('articles').append(emptyState(data.updatedAt ? 'לא נמצאו עדכונים לסינון הזה.' : 'התמונה עדיין מתעדכנת.', data.updatedAt ? 'אפשר לשנות את החיפוש, המקור או הקטגוריה.' : 'העדכון הראשון מהמקורות טרם התקבל. אפשר לחזור בעוד כמה דקות.', !data.updatedAt));
    $('result-count').textContent = `${data.total} עדכונים`;
    $('more').hidden = state.offset >= data.total;
    $('freshness').textContent = data.updatedAt ? `${data.stale ? 'העדכון האחרון' : 'עודכן'} · ${timeFormat.format(new Date(data.updatedAt))}` : 'ממתינים לעדכון הראשון';
    const selected = $('category').value;
    $('category').replaceChildren(new Option('כל הקטגוריות', ''), ...data.categories.map((category) => new Option(category, category)));
    if (data.categories.includes(selected)) $('category').value = selected;
    renderSources(data.sources);
    const notices = [];
    if (data.stale && data.updatedAt) notices.push('העדכונים המוצגים אינם עדכניים. זמני הפרסום מופיעים לצד כל ידיעה.');
    if (data.articles.some((article) => article.rewriteStatus !== 'rewritten')) notices.push('חלק מהכותרות מוצגות בנוסח המקורי ומסומנות בהתאם.');
    if (data.sources.some((source) => source.state === 'unavailable' || source.state === 'partial')) notices.push('חלק מהמקורות אינם מתעדכנים במלואם כרגע.');
    $('notice').textContent = notices.join(' '); $('notice').hidden = notices.length === 0;
  } catch (error) {
    if (error.name === 'AbortError' || requestId !== state.requestId) return;
    if (!append) { $('articles').replaceChildren(emptyState('העדכונים לא זמינים כרגע.', 'אפשר לנסות שוב בעוד רגע, או לקרוא ישירות באחד המקורות.', true)); $('result-count').textContent = ''; $('more').hidden = true; }
    else { $('notice').textContent = 'לא הצלחנו לטעון עדכונים נוספים. אפשר לנסות שוב.'; $('notice').hidden = false; }
    $('freshness').textContent = 'העדכון אינו זמין כרגע';
  } finally {
    if (requestId === state.requestId) { state.loading = false; $('articles').setAttribute('aria-busy', 'false'); $('more').disabled = false; }
  }
}

$('filters').addEventListener('submit', (event) => { event.preventDefault(); load(); });
for (const field of ['source', 'category']) $(field).addEventListener('change', () => load());
$('search').addEventListener('search', () => load());
for (const order of ['broad', 'latest']) $(order).addEventListener('click', () => {
  state.order = order;
  for (const option of ['broad', 'latest']) $(option).setAttribute('aria-pressed', String(option === order));
  $('view-explanation').textContent = order === 'broad' ? 'סבב בין קטגוריות ומקורות, כדי לראות יותר מהתמונה.' : 'הפרסומים החדשים ביותר תחילה, לפי זמן הפרסום במקור.';
  load();
});
$('more').addEventListener('click', () => load(true));
renderSources([{ id: 'ynet', name: 'ynet', domain: 'ynet.co.il' }, { id: 'kan', name: 'כאן', domain: 'kan.org.il' }, { id: 'n12', name: 'N12', domain: 'n12.co.il' }, { id: 'mako', name: 'mako', domain: 'mako.co.il' }]);
load();

// Probe worker used only by scripts/pipeline-check.js. It injects a deterministic
// mock model into a real NewsStore so the refresh/rewrite/verify/budget orchestration
// runs under workerd without any external inference.
import worker, { NewsStore } from '../src/worker.js';

const validatorDefault = '@cf/cloudflare/clef-flash';

function createMockAI(validatorModel, rewriteMode) {
  const calls = { rewrite: 0, verify: 0 };
  const run = async (model, input) => {
    if (model === validatorModel) {
      calls.verify++;
      // clef answers are `noul` probabilities keyed by the candidate index.
      const answers = {};
      input.state.forEach((item, index) => {
        answers[`${index}_supported`] = { type: 'noul', noul: 1 };
        answers[`${index}_preserved`] = { type: 'noul', noul: /\/2$/.test(item.id) ? 0 : 1 };
      });
      return { model: 'clef-flash', answers, usage: { input_tokens: 1000, output_tokens: 0 } };
    }
    calls.rewrite++;
    // A model that returns unparseable output must be surfaced, not reported as ok.
    if (rewriteMode === 'invalid') return { response: 'not json' };
    const items = JSON.parse(input.messages[1].content);
    return { response: JSON.stringify({ items: items.map((item) => ({ id: item.id, usable: true,
      headline: /\/2$/.test(item.id) ? 'ראשי ערים קראו לשינוי דמוגרפי בישראל' : 'לפי המועצה אושרו 3 תוכניות' })) }) };
  };
  return { calls, run };
}

export class PipelineStore extends NewsStore {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/run' && request.method === 'POST') {
      const body = await request.json();
      const mock = createMockAI(body.env?.VALIDATOR_MODEL || validatorDefault, body.env?.MOCK_REWRITE);
      this.env = { ...this.env, ...(body.env || {}), AI: mock };
      if (body.snapshot) this.writeSnapshot(body.snapshot);
      const result = await this.refresh();
      return Response.json({ result, calls: mock.calls });
    }
    if (url.pathname === '/usage') return Response.json({ used: this.readUsage(url.searchParams.get('day') || this.usageDay()) });
    return super.fetch(request);
  }
}

export default worker;

// Integration check: a rewrite cached under an older pipeline must never be served,
// even when no inference is available to replace it. The wrong cached headline is
// seeded directly into the Durable Object, then read back through the real API.
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { build } from 'esbuild';
import { Miniflare, convertV4MiniflareOptions } from 'miniflare';
import { DEFAULT_REWRITE_MODEL, policyFingerprint, sourceFingerprint } from '../src/policy.js';

const directory = await mkdtemp(join(process.cwd(), '.probe-'));
const outfile = join(directory, 'probe.js');
await build({ entryPoints: ['scripts/retirement-probe.js'], bundle: true, format: 'esm', platform: 'browser', target: 'es2022', outfile });

const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, name: 'positivity-bias', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'SeedableStore', useSQLite: true } },
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } }
}));

try {
  await mf.ready;
  const namespace = await mf.getDurableObjectNamespace('NEWS');
  const store = namespace.get(namespace.idFromName('edition'));
  const now = new Date().toISOString();
  // Mirror the real pre-correction (bootstrap) snapshot: the old pipeline stored
  // `<model>:editorial-v2` on each rewrite and no snapshot-level policy fingerprint.
  // The correction must retire exactly that state on first serve, without inference.
  const legacyFingerprint = `${DEFAULT_REWRITE_MODEL}:editorial-v2`;
  const article = { id: 'drone-1', url: 'https://www.ynet.co.il/news/article/1', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'התעשייה האווירית השלימה בהצלחה ניסוי במל״ט שמצויד במקלע',
    headline: 'תעשייה אווירית: ניסוי במל״ט עם מקלע נכשל', rewriteStatus: 'rewritten',
    rewriteFingerprint: legacyFingerprint, verification: { supported: true }, context: 'x'.repeat(4000),
    categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  // A partial/legacy snapshot can lose the decision marker entirely while still
  // holding a wrong generated headline. With no fingerprint it must not be served.
  const orphan = { id: 'orphan-2', url: 'https://www.ynet.co.il/news/article/2', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'המועצה אישרה 7 תוכניות חדשות',
    headline: 'המועצה דחתה 7 תוכניות חדשות',
    categories: ['חדשות'], publishedAt: new Date(Date.now() - 60_000).toISOString(), description: 'תיאור' };
  // A snapshot that lost the generated headline entirely must still restore the original.
  const headless = { id: 'headless-3', url: 'https://www.ynet.co.il/news/article/3', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'הצעת החוק אושרה בקריאה ראשונה', categories: ['חדשות'],
    publishedAt: new Date(Date.now() - 120_000).toISOString(), description: 'תיאור' };
  const seeded = { articles: [article, orphan, headless], updatedAt: now, lastAttemptAt: now,
    rewriteStatus: 'ok', sources: [] };
  assert.equal(seeded.policyFingerprint, undefined); // the old snapshot had no policy fingerprint
  const seed = await store.fetch('https://news.internal/seed', { method: 'POST', body: JSON.stringify(seeded) });
  assert.equal(seed.status, 200);

  const api = await (await mf.dispatchFetch('https://fixture.local/api/news')).json();
  const byId = new Map(api.articles.map((entry) => [entry.id, entry]));
  const served = byId.get(article.id);
  assert.equal(served.headline, article.originalHeadline);
  assert.equal(served.rewriteStatus, 'original');
  assert.equal(served.rewriteFingerprint, undefined);
  assert.deepEqual(served.categories, ['חדשות']);
  const orphanServed = byId.get(orphan.id);
  assert.equal(orphanServed.headline, orphan.originalHeadline); // no fingerprint: never served
  assert.equal(orphanServed.rewriteStatus, 'original');
  const headlessServed = byId.get(headless.id);
  assert.equal(headlessServed.headline, headless.originalHeadline); // lost headline restored, never empty
  assert.equal(headlessServed.rewriteStatus, 'original');

  // The idempotent migration persisted: a later read still shows the originals.
  const again = await (await store.fetch('https://news.internal/snapshot')).json();
  for (const entry of again.articles) assert.equal(entry.headline, entry.originalHeadline);
  assert.ok(again.policyFingerprint);
  assert.notEqual(again.policyFingerprint, legacyFingerprint);

  // Serve-time enforcement is article-level, not flag-level: even when the snapshot
  // already carries the ACTIVE policy fingerprint, a stale/headless cached headline is
  // retired on read, while a genuinely current rewrite is kept.
  const active = policyFingerprint({});
  const staleArticle = { id: 'stale-3', url: 'https://www.ynet.co.il/news/article/3', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'המועצה אישרה 5 תוכניות', headline: 'המועצה דחתה 5 תוכניות', rewriteStatus: 'rewritten',
    rewriteFingerprint: 'old-policy', categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  const headlessArticle = { id: 'headless-4', url: 'https://www.ynet.co.il/news/article/4', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'הצעת החוק אושרה בקריאה ראשונה', categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  const trusted = { id: 'trusted-5', url: 'https://www.ynet.co.il/news/article/5', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'העירייה תפתח 2 גנים חדשים', headline: 'העירייה תפתח 2 גנים חדשים בשכונה', rewriteStatus: 'rewritten',
    rewriteFingerprint: active, categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  // A partial persist can leave the ACTIVE fingerprint/status set while losing the
  // generated headline. That decision is not displayable and must restore the original
  // rather than serve an empty headline.
  const trustedHeadless = { id: 'trusted-headless-6', url: 'https://www.ynet.co.il/news/article/6', sourceId: 'ynet', sourceName: 'ynet',
