  cf: false, name: 'positivity-bias', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'SeedableStore', useSQLite: true } },
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } }
}));

try {
  await mf.ready;
  const namespace = await mf.getDurableObjectNamespace('NEWS');
  const store = namespace.get(namespace.idFromName('edition'));
  const now = new Date().toISOString();
  // Mirror the real pre-correction (bootstrap) snapshot: the old pipeline stored
  // `<model>:editorial-v2` on each rewrite and no snapshot-level policy fingerprint.
  // The correction must retire exactly that state on first serve, without inference.
  const legacyFingerprint = `${DEFAULT_REWRITE_MODEL}:editorial-v2`;
  const article = { id: 'drone-1', url: 'https://www.ynet.co.il/news/article/1', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'התעשייה האווירית השלימה בהצלחה ניסוי במל״ט שמצויד במקלע',
    headline: 'תעשייה אווירית: ניסוי במל״ט עם מקלע נכשל', rewriteStatus: 'rewritten',
    rewriteFingerprint: legacyFingerprint, verification: { supported: true }, context: 'x'.repeat(4000),
    categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  // A partial/legacy snapshot can lose the decision marker entirely while still
  // holding a wrong generated headline. With no fingerprint it must not be served.
  const orphan = { id: 'orphan-2', url: 'https://www.ynet.co.il/news/article/2', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'המועצה אישרה 7 תוכניות חדשות',
    headline: 'המועצה דחתה 7 תוכניות חדשות',
    categories: ['חדשות'], publishedAt: new Date(Date.now() - 60_000).toISOString(), description: 'תיאור' };
  // A snapshot that lost the generated headline entirely must still restore the original.
  const headless = { id: 'headless-3', url: 'https://www.ynet.co.il/news/article/3', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'הצעת החוק אושרה בקריאה ראשונה', categories: ['חדשות'],
    publishedAt: new Date(Date.now() - 120_000).toISOString(), description: 'תיאור' };
  const seeded = { articles: [article, orphan, headless], updatedAt: now, lastAttemptAt: now,
    rewriteStatus: 'ok', sources: [] };
  assert.equal(seeded.policyFingerprint, undefined); // the old snapshot had no policy fingerprint
  const seed = await store.fetch('https://news.internal/seed', { method: 'POST', body: JSON.stringify(seeded) });
  assert.equal(seed.status, 200);

  const api = await (await mf.dispatchFetch('https://fixture.local/api/news')).json();
  const byId = new Map(api.articles.map((entry) => [entry.id, entry]));
  const served = byId.get(article.id);
  assert.equal(served.headline, article.originalHeadline);
  assert.equal(served.rewriteStatus, 'original');
  assert.equal(served.rewriteFingerprint, undefined);
  assert.deepEqual(served.categories, ['חדשות']);
  const orphanServed = byId.get(orphan.id);
  assert.equal(orphanServed.headline, orphan.originalHeadline); // no fingerprint: never served
  assert.equal(orphanServed.rewriteStatus, 'original');
  const headlessServed = byId.get(headless.id);
  assert.equal(headlessServed.headline, headless.originalHeadline); // lost headline restored, never empty
  assert.equal(headlessServed.rewriteStatus, 'original');

  // The idempotent migration persisted: a later read still shows the originals.
  const again = await (await store.fetch('https://news.internal/snapshot')).json();
  for (const entry of again.articles) assert.equal(entry.headline, entry.originalHeadline);
  assert.ok(again.policyFingerprint);
  assert.notEqual(again.policyFingerprint, legacyFingerprint);

  // Serve-time enforcement is article-level, not flag-level: even when the snapshot
  // already carries the ACTIVE policy fingerprint, a stale/headless cached headline is
  // retired on read, while a genuinely current rewrite is kept.
  const active = policyFingerprint({});
  const staleArticle = { id: 'stale-3', url: 'https://www.ynet.co.il/news/article/3', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'המועצה אישרה 5 תוכניות', headline: 'המועצה דחתה 5 תוכניות', rewriteStatus: 'rewritten',
    rewriteFingerprint: 'old-policy', categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  const headlessArticle = { id: 'headless-4', url: 'https://www.ynet.co.il/news/article/4', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'הצעת החוק אושרה בקריאה ראשונה', categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  const trusted = { id: 'trusted-5', url: 'https://www.ynet.co.il/news/article/5', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'העירייה תפתח 2 גנים חדשים', headline: 'העירייה תפתח 2 גנים חדשים בשכונה', rewriteStatus: 'rewritten',
    rewriteFingerprint: active, categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  // A partial persist can leave the ACTIVE fingerprint/status set while losing the
  // generated headline. That decision is not displayable and must restore the original
  // rather than serve an empty headline.
  const trustedHeadless = { id: 'trusted-headless-6', url: 'https://www.ynet.co.il/news/article/6', sourceId: 'ynet', sourceName: 'ynet',
    originalHeadline: 'הנמל ייפתח מחדש בשבוע הבא', headline: undefined, rewriteStatus: 'rewritten',
    rewriteFingerprint: active, categories: ['חדשות'], publishedAt: now, description: 'תיאור' };
  const rejectedSeed = { ...trustedHeadless, id: 'trusted-rejected-7', headline: '', rewriteStatus: 'rejected' };
  rejectedSeed.rewriteSource = sourceFingerprint(rejectedSeed);
  await store.fetch('https://news.internal/seed', { method: 'POST', body: JSON.stringify({ articles: [staleArticle, headlessArticle, trusted, trustedHeadless, rejectedSeed],
    updatedAt: now, lastAttemptAt: now, policyFingerprint: active, rewriteStatus: 'ok', sources: [] }) });
  const forced = await (await mf.dispatchFetch('https://fixture.local/api/news')).json();
  const forcedById = new Map(forced.articles.map((entry) => [entry.id, entry]));
  assert.equal(forcedById.get(staleArticle.id).headline, staleArticle.originalHeadline);
  assert.equal(forcedById.get(headlessArticle.id).headline, headlessArticle.originalHeadline);
  assert.equal(forcedById.get(trusted.id).headline, trusted.headline);
  assert.equal(forcedById.get(trusted.id).rewriteStatus, 'rewritten');
  assert.equal(forcedById.get(trustedHeadless.id).headline, trustedHeadless.originalHeadline); // trusted but headless: restored
  assert.equal(forcedById.get(trustedHeadless.id).rewriteStatus, 'original');
  assert.equal(forcedById.get(rejectedSeed.id).headline, rejectedSeed.originalHeadline); // empty rejected headline: restored
  assert.equal(forcedById.get(rejectedSeed.id).rewriteStatus, 'original');

  console.log('Retirement passed: a stale cached headline is never served and the migration persists without inference.');
} finally { await mf.dispose().catch(() => {}); await rm(directory, { recursive: true, force: true }).catch(() => {}); }

// Probe worker used only by scripts/extraction-check.js. It exercises the real
// HTMLRewriter body extraction under workerd, which plain Node cannot provide.
import { prepareContext, readArticleData } from '../src/extract.js';

// The article intentionally contains a self-closing SVG <path>: the parser never
// closes it, and registering an end-tag handler for it used to abort extraction with
// "Parser error: No end tag." on real publisher pages.
const articleHtml = `<!doctype html><html lang="he"><head>
  <title>אתר הדגמה</title>
  <meta property="og:title" content="התעשייה האווירית השלימה ניסוי">
  <script type="application/ld+json">{"@type":"NewsArticle","headline":"התעשייה האווירית השלימה בהצלחה ניסוי במל״ט","articleSection":"בטחון","datePublished":"2026-10-13T10:00:00Z"}</script>
</head><body>
  <header class="masthead"><nav><a href="/">דף הבית</a><a href="/sport">ספורט</a></nav></header>
  <main><article>
    <h1>התעשייה האווירית השלימה בהצלחה ניסוי במל״ט</h1>
    <svg class="icon" aria-hidden="true"><path d="M0 0h32L0 32Z"/></svg>
    <p>התעשייה האווירית הודיעה כי השלימה בהצלחה ניסוי במל״ט שמצויד במקלע.</p>
    <div class="ad-banner">פרסומת</div>
    <p>הניסוי נערך באזור דרומי ונחשב להצלחה מלאה.</p>
    <aside class="related-articles"><p>כתבות נוספות</p></aside>
  </article></main>
  <div class="recommended"><p>מומלץ עבורך</p></div>
  <footer><p>כל הזכויות שמורות</p></footer>
</body></html>`;

// A bot-mitigation interstitial served in place of the article.
const blockHtml = `<!doctype html><html lang="en"><head><title>Radware Block Page</title></head>
  <body><main><p>We are sorry... but your activity and behavior on this website made us think that you are a bot. To protect this website, we cannot process your request right now. Please solve this CAPTCHA in helping us understand your behavior to grant access.</p></main></body></html>`;

// A client-rendered shell whose initial HTML is only navigation chrome.
const thinHtml = `<!doctype html><html lang="he"><body><nav><a href="/">דף הבית</a><a href="/sport">ספורט</a></nav><main><p>טוען את הכתבה</p></main></body></html>`;

const pages = { article: articleHtml, block: blockHtml, thin: thinHtml };

export default {
  async fetch(request) {
    const which = new URL(request.url).searchParams.get('case') || 'article';
    const data = await readArticleData(pages[which] || articleHtml);
    const context = prepareContext(data.body);
    return Response.json({ case: which, headline: data.headline, categories: data.categories,
      body: context.text, charCount: context.charCount, completeness: context.completeness });
  }
};

// Integration regression: when many full-text articles are pending, the shared
// rewrite+verify batches must be split so that no verification request exceeds the
// validator's context window. A rewrite-only plan (Llama's 128k window) would pack
// ~20 articles (~80k tokens) into one request against clef-flash's 32k window.
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { build } from 'esbuild';
import { Miniflare, convertV4MiniflareOptions } from 'miniflare';
import { ESTIMATED_CHARS_PER_TOKEN } from '../src/budget.js';
import { MODEL_CONTEXT_TOKENS } from '../src/policy.js';

const directory = await mkdtemp(join(process.cwd(), '.probe-'));
const outfile = join(directory, 'probe.js');
await build({ entryPoints: ['scripts/batch-probe.js'], bundle: true, format: 'esm', platform: 'browser', target: 'es2022', outfile });

const COUNT = 9;
const now = Date.now();
// Each page body is long enough to be truncated at the 6000-char context cap, so the
// plan must split a 9-article pending set across multiple 32k-token requests.
const longBody = 'המועצה דנה בתכניות הפיתוח של האזור ובהשלכותיהן על התושבים. '.repeat(200);

const fixture = async (request) => {
  const match = /^\/page\/(\d+)$/.exec(new URL(request.url).pathname);
  if (!match) return new Response('not found', { status: 404 });
  const n = Number(match[1]);
  const html = `<!doctype html><html lang="he"><head>
    <script type="application/ld+json">${JSON.stringify({ '@type': 'NewsArticle', headline: `עדכון כללי ${n}`, articleSection: 'בארץ' })}</script>
  </head><body><nav>ניווט באתר</nav><article><h1>עדכון כללי</h1><p>${longBody}</p></article><div class="related"><p>כתבות קשורות</p></div></body></html>`;
  return new Response(html, { headers: { 'content-type': 'text/html' } });
};

const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, name: 'positivity-bias', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'BatchStore', useSQLite: true } },
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } },
  outboundService: fixture
}));

try {
  await mf.ready;
  const namespace = await mf.getDurableObjectNamespace('NEWS');
  const store = namespace.get(namespace.idFromName('edition'));
  const articles = Array.from({ length: COUNT }, (_, index) => ({
    id: `https://www.ynet.co.il/page/${index + 1}`, url: `https://www.ynet.co.il/page/${index + 1}`,
    sourceId: 'ynet', sourceName: 'ynet', originalHeadline: `עדכון כללי ${index + 1}`, headline: `עדכון כללי ${index + 1}`,
    description: 'תיאור', categories: ['בארץ'], publishedAt: new Date(now - 60_000).toISOString(), rewriteStatus: 'original'
  }));
  const seeded = { articles, updatedAt: new Date(now - 60_000).toISOString(),
    lastAttemptAt: new Date(now - 2 * 3_600_000).toISOString(), policyFingerprint: null, rewriteStatus: 'not_configured', sources: [] };
  const run = await (await store.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: seeded,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '6000', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '20' } }) })).json();
  assert.equal(run.result.state, 'complete');
  assert.equal(run.result.rewriteStatus, 'ok');
  assert.equal(run.result.articles, COUNT);
  // The shared batch is split by the smaller (validator) window, not the rewrite model's.
  assert.ok(run.calls.rewrite > 1, `expected split batches, got ${run.calls.rewrite}`);
  assert.equal(run.calls.verify, run.calls.rewrite);
  const window = MODEL_CONTEXT_TOKENS['@cf/cloudflare/clef-flash'];
  const verifyTokens = Math.ceil(run.calls.maxVerifyChars / ESTIMATED_CHARS_PER_TOKEN);
  assert.ok(verifyTokens <= window, `verification request ~${verifyTokens} tokens exceeds validator window ${window}`);
  assert.ok(run.calls.maxRewriteChars <= run.calls.maxVerifyChars + 200, 'rewrite request is not larger than verification');

  const api = await (await mf.dispatchFetch('https://fixture.local/api/news?limit=120')).json();
  assert.equal(api.total, COUNT);
  assert.ok(api.articles.every((article) => article.rewriteStatus === 'rewritten'));
  assert.ok(api.articles.every((article) => !('context' in article) && !('verification' in article)));
  const day = new Date().toISOString().slice(0, 10);
  const usage = await (await store.fetch(`https://news.internal/usage?day=${day}`)).json();
  assert.ok(usage.used > 0 && usage.used <= 6000, `unexpected usage ${usage.used}`);

  // Budget-aware sizing: when only part of a planned batch fits the remaining daily
  // budget, the request must be REDUCED rather than deferring every article. A fresh
  // Durable Object starts with a zero ledger, so the exact fit is deterministic.
  const partialStore = namespace.get(namespace.idFromName('partial'));
  const partialSeed = { articles, updatedAt: new Date(now - 60_000).toISOString(),
    lastAttemptAt: new Date(now - 2 * 3_600_000).toISOString(), policyFingerprint: null, rewriteStatus: 'not_configured', sources: [] };
  const partial = await (await partialStore.fetch('https://news.internal/run', { method: 'POST', body: JSON.stringify({ snapshot: partialSeed,
    env: { REWRITE_MODEL: '@cf/meta/llama-3.1-8b-instruct-fp8-fast', VALIDATOR_MODEL: '@cf/cloudflare/clef-flash',
      DAILY_NEURON_BUDGET: '60', CONTEXT_CHARS: '6000', MAX_CONTEXT_FETCHES: '20' } }) })).json();
  assert.equal(partial.result.state, 'complete');
  // The 60-neuron budget cannot cover all nine articles at once, but the first planned
  // batch is REDUCED to what fits instead of deferring every article in it. Reporting
  // provider usage lets the ledger free headroom, so a small prefix still gets through.
  assert.ok(partial.calls.rewrite >= 1, `expected a reduced batch, got ${partial.calls.rewrite}`);
  assert.ok(partial.calls.rewrite < COUNT, `all ${COUNT} articles were processed; budget reduction not exercised`);
  assert.equal(partial.calls.verify, partial.calls.rewrite);
  const partialSnapshot = await (await partialStore.fetch('https://news.internal/snapshot')).json();
  const rewritten = partialSnapshot.articles.filter((article) => article.rewriteStatus === 'rewritten').length;
  assert.equal(rewritten, partial.calls.rewrite);
  assert.equal(partialSnapshot.articles.filter((article) => article.rewriteStatus === 'original').length, COUNT - rewritten);
  const partialUsage = await (await partialStore.fetch('https://news.internal/usage')).json();
  assert.ok(partialUsage.used > 0 && partialUsage.used <= 60, `partial usage overspent: ${partialUsage.used}`);

  console.log(`Batch passed: ${COUNT} full-text articles split into ${run.calls.rewrite} requests, each verification within the ${window}-token validator window; usage ${Math.round(usage.used)} neurons; a 60-neuron budget processes a reduced prefix (${partial.calls.rewrite}) instead of deferring all nine.`);
} finally { await mf.dispose().catch(() => {}); await rm(directory, { recursive: true, force: true }).catch(() => {}); }

