// Temporary local probe (not shipped): real-network ingestion + full-text extraction.
import configuration from '../websites.json';
import { validateWebsites } from '../src/news.js';
import { ingestSource, loadArticleContext } from '../src/ingest.js';

const sources = validateWebsites(configuration);

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const source = sources.find((s) => s.id === url.searchParams.get('source'));
    if (!source) return new Response('unknown source', { status: 400 });
    if (url.pathname === '/ingest') {
      const result = await ingestSource(source, [], Date.now());
      return Response.json({ status: result.status, count: result.articles.length,
        sample: result.articles.slice(0, 10).map((a) => ({ url: a.url, headline: a.originalHeadline, categories: a.categories })) });
    }
    const target = url.searchParams.get('url');
    const loaded = await loadArticleContext({ url: target, sourceId: source.id }, source, fetch, { maxChars: 6000 });
    return Response.json({ url: target, completeness: loaded.context.completeness, charCount: loaded.context.charCount,
      bodyChars: loaded.bodyChars, error: loaded.error || null, headline: loaded.headline || null,
      bodySnippet: loaded.context.text.slice(0, 160) });
  }
};

import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { build } from 'esbuild';
import { Miniflare, convertV4MiniflareOptions } from 'miniflare';

const directory = await mkdtemp(join(process.cwd(), '.live-'));
const outfile = join(directory, 'probe.js');
await build({ entryPoints: ['scripts/live-probe.js'], bundle: true, format: 'esm', platform: 'browser', target: 'es2022', outfile });

const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, name: 'positivity-bias', scriptPath: outfile, modules: true, compatibilityDate: '2026-10-13'
}));

const withTimeout = (promise, ms) => Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error('probe_timeout')), ms))]);

try {
  await mf.ready;
  for (const id of ['ynet', 'kan', 'n12', 'mako']) {
    try {
      const result = await withTimeout((await mf.dispatchFetch(`https://probe.local/ingest?source=${id}`)).json(), 90_000);
      console.log(`INGEST ${id}: ${result.status.state} received=${result.status.received} sample=${result.count} errors=${JSON.stringify(result.status.errors).slice(0, 300)}`);
      for (const article of result.sample) console.log(`   ${article.url} | ${article.categories.join(',')} | ${article.headline.slice(0, 90)}`);
    } catch (error) { console.log(`INGEST ${id}: FAILED ${error.message}`); }
  }
  // Extraction is sampled from the URLs the ingest reported above via a second call.
  const probes = JSON.parse(process.env.LIVE_PROBE_URLS || '[]');
  for (const probe of probes) {
    try {
      const result = await withTimeout((await mf.dispatchFetch(`https://probe.local/context?source=${probe.source}&url=${encodeURIComponent(probe.url)}`)).json(), 60_000);
      console.log(`CONTEXT ${probe.source} ${result.completeness} chars=${result.charCount}/${result.bodyChars} err=${result.error} headline=${(result.headline || '').slice(0, 70)} snippet=${(result.bodySnippet || '').slice(0, 80)}`);
    } catch (error) { console.log(`CONTEXT ${probe.source}: FAILED ${error.message}`); }
  }
} finally { await mf.dispose().catch(() => {}); await rm(directory, { recursive: true, force: true }).catch(() => {}); }

